#include <stdio.h>

#define MAX_BOWLS 5

int bowls[MAX_BOWLS];
int top = 0;

int is_full(void) { return top == MAX_BOWLS; }
int is_empty(void) { return top == 0; }

int push(int value) {
    if (is_full()) {
        return 0;
    }
    bowls[top] = value;
    top++;
    return 1;
}

int pop(int *value) {
    if (is_empty()) {
        return 0;
    }
    top--;
    *value = bowls[top];
    return 1;
}

int main(void) {
    push({a});
    push({b});
    push({c});
    printf("摞了 %d 只碗\n", top);
    int v = 0;
    while (pop(&v)) {
        printf("取到 %d\n", v);
    }
    printf("空了吗？%s\n", is_empty() ? "空了" : "还有");
    return 0;
}
